import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function crafted to exhibit specific ELA characteristics.

    This function combines a modified Rastrigin function with added linear and interaction terms
    to create a complex and challenging search space.

    Formula:
    f(x) = rastrigin_modified(x) + linear_term(x) + interaction_term(x)

    where rastrigin_modified introduces modality and ruggedness, linear_term adds a linear bias,
    and interaction_term introduces dependencies between variables.
    """

    def rastrigin_modified(x):
        """Modified Rastrigin function (symmetrized)."""
        n = len(x)
        A = 10
        return np.sum(x**2 - A * np.cos(2 * np.pi * x) + A)

    def linear_term(x):
        """Linear term to influence linear ELA features."""
        return 0.5 * np.sum(x)

    def interaction_term(x):
        """Interaction term with a stronger influence."""
        n = len(x)
        interaction = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                interaction += x[i] * np.sin(x[j])  # Changed interaction.
        return 0.1 * interaction

    return 0.3 * rastrigin_modified(x) + linear_term(x) + interaction_term(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function with targeted ELA characteristics.

    This function combines a modified Rastrigin function, a scaled interaction term,
    and an linear interaction to introduce modality, ruggedness, and epistasis,
    resulting in a complex search space.

    Formula:
    f(x) = scale * (rastrigin_modified(x) + interaction_term(x) + lin_interaction(x))
    """

    def rastrigin_modified(x):
        """Modified Rastrigin function with increased amplitude."""
        n = len(x)
        A = 20  # Increased amplitude
        return np.sum((x**2 - A * np.cos(2 * np.pi * x) + A) * (1 + 0.1*np.arange(n)))

    def interaction_term(x):
        """Interaction term using products of sine functions with increased frequency."""
        n = len(x)
        interaction = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                interaction += np.sin(3 * x[i]) * np.sin(3 * x[j]) # Increased frequency
        return 0.2 * interaction  # Scale up the interaction

    def lin_interaction(x):
        """ Introduces linear interaction to reduce quadratic measures """
        n = len(x)
        interaction = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                interaction += x[i] * np.sin(x[j])
        return 0.1*interaction

    scale = 5.0  # Scaling to drastically influence the fitness std.
    return scale * (rastrigin_modified(x) + interaction_term(x) + lin_interaction(x))

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed for ELA targeting.

    This function combines a modified sphere function with a high condition number matrix,
    a sum of cosines with different frequencies, and an interaction term. This induces
    a complex landscape with characteristics suitable for ELA targetting.

    Formula:
    f(x) = scale * (ellipsoidal(x) + cos_sum(x) + interaction_term(x))
    """

    def ellipsoidal(x):
        """Ellipsoidal function with condition number imbalance."""
        n = len(x)
        weights = np.power(10.0, np.linspace(0, 3, n))  # High condition number
        return np.sum(weights * x**2)

    def cos_sum(x):
        """Sum of cosine functions with varying frequencies to add modality."""
        n = len(x)
        freqs = np.linspace(1, 7, n)
        return np.sum(np.cos(freqs * x))

    def interaction_term(x):
        """Interaction term to introduce non-separability."""
        n = len(x)
        interaction = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                interaction += x[i] * np.sin(x[j])
        return 0.1 * interaction

    scale = 0.01 #Adjusted, it was previously 5.0
    return scale * (ellipsoidal(x) + cos_sum(x) + interaction_term(x))

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function with targeted ELA characteristics.

    This function combines a modified Rastrigin function, a scaled interaction term,
    and a linear interaction to introduce modality, ruggedness, and epistasis,
    resulting in a complex search space.

    Formula:
    f(x) = scale * (rastrigin_modified(x) + interaction_term(x) + lin_interaction(x))
    """

    def rastrigin_modified(x):
        """Modified Rastrigin function with increased amplitude."""
        n = len(x)
        A = 20  # Increased amplitude
        return np.sum((x**2 - A * np.cos(2 * np.pi * x) + A) * (1 + 0.1*np.arange(n)))

    def interaction_term(x):
        """Interaction term using products of sine functions with increased frequency."""
        n = len(x)
        interaction = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                interaction += np.sin(3 * x[i]) * np.sin(3 * x[j]) # Increased frequency
        return 0.4 * interaction  # Scale up the interaction stronger

    def lin_interaction(x):
        """ Introduces linear interaction to impose correlation with objective and reduce quadratic measures """
        n = len(x)
        interaction = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                interaction += x[i] * np.sin(x[j]) + 0.1 * x[i] * x[j] # Added correlation term
        return 0.1*interaction

    scale = 15.0  # Scaling to drastically influence the fitness std.
    return scale * (rastrigin_modified(x) + interaction_term(x) + lin_interaction(x))

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining quadratic, sinusoidal, and distance components to target specific ELA features.

    Formula:
    f(x) = scale * (quad_base(x) * np.exp(sin_mod(x)) + dist_term(x))

    where:
    - x is the input vector
    - quad_base(x) = sum(x_i^2)
    - sin_mod(x) = sum(sin(x_i))
    - dist_term(x) = norm(x)
    """
    n = len(x)
    scale = 0.5

    def quad_base(x):
        return np.sum(x**2)

    def sin_mod(x):
        return np.sum(np.sin(x))

    def dist_term(x):
        return np.linalg.norm(x) # Calculate Euclidean distance

    return scale * (quad_base(x) * np.exp(sin_mod(x) / n) + 0.1 * dist_term(x))
